def FUTURE_BLOCKCIPHER(r=None, version=None, copy_operator=False):
    p = [var.Variable(1, ID="p" + str(i)) for i in range(64)]
    k = [var.Variable(1, ID="k" + str(i)) for i in range(128)]
    c = [var.Variable(1, ID="c" + str(i)) for i in range(64)]
    cipher = FUTURE_block_cipher("FUTURE", p, k, c, nbr_rounds=r)
    cipher.post_initialization(copy_operator=copy_operator)
    return cipher
